module cli

import compress.deflate
import strings
import time
import vaxis

const boo_compressed = $embed_file('framedata.compressed')
const boo_frame_width = 100
const boo_frame_height = 41
const boo_frame_rate = 1000 / 30

pub struct BooOptions {}

pub fn (opts BooOptions) deinit() {
	_ = opts
}

pub fn (opts BooOptions) help() ! {
	_ = opts
	action_options_help()!
}

enum BooParseState as u8 {
	normal
	span
	in_tag
	in_closing_tag
}

// decompress_boo_frames expands the exact frame data generated by Ghostty's
// src/build/framegen utility and splits it on the same byte separator.
fn decompress_boo_frames() ![]string {
	data := deflate.decompress(boo_compressed.to_bytes())!
	return data.bytestr().split('\x01')
}

// style_boo_line translates the HTML-span markup used by Ghostty's website
// frames to the blue ANSI style used by the terminal animation.
fn style_boo_line(line string) (string, int) {
	mut state := BooParseState.normal
	mut visible := 0
	mut out := strings.new_builder(line.len)
	for codepoint in line.runes() {
		match state {
			.normal {
				if codepoint == `<` {
					state = .in_tag
					out.write_string('\x1b[34m')
					continue
				}
			}
			.span {
				if codepoint == `<` {
					state = .in_tag
					out.write_string('\x1b[39m')
					continue
				}
			}
			.in_tag {
				if codepoint == `/` {
					state = .in_closing_tag
				} else if codepoint == `>` {
					state = .span
				}
				continue
			}
			.in_closing_tag {
				if codepoint == `>` {
					state = .normal
				}
				continue
			}
		}

		out.write_rune(codepoint)
		visible++
	}
	return out.str(), visible
}

// draw_boo_frame returns one centered animation frame for the current terminal
// dimensions, or Ghostty's minimum-size warning.
fn draw_boo_frame(frame string, width int, height int) !string {
	mut out := strings.new_builder(boo_frame_width * boo_frame_height * 2)
	out.write_string(vaxis.clear_screen())
	if width < boo_frame_width || height < boo_frame_height {
		message := 'Screen must be at least 100w x 41h'
		out.write_string(vaxis.position((height - 1) / 2, (width - message.runes().len) / 2))
		out.write_string(message)
		return out.str()
	}

	mut lines := frame.split('\n')
	if lines.len > 0 && lines.last() == '' {
		lines.delete_last()
	}
	if lines.len != boo_frame_height {
		return error('invalid boo frame height: ${lines.len}')
	}
	offset_y := (height - boo_frame_height) / 2
	offset_x := (width - boo_frame_width) / 2
	for row, line in lines {
		styled, visible := style_boo_line(line)
		if visible != boo_frame_width {
			return error('invalid boo frame width on row ${row}: ${visible}')
		}
		out.write_string(vaxis.position(offset_y + row, offset_x))
		out.write_string(styled)
	}
	return out.str()
}

// run_boo displays the Ghostty website animation at 30 frames per second until
// the user presses Ctrl-C or Escape.
pub fn run_boo(args []string) !int {
	_ := parse_action_options[BooOptions](args)!
	frames := decompress_boo_frames()!
	if frames.len == 0 {
		return error('boo animation has no frames')
	}

	mut tty := vaxis.Tty.new()
	mut frame := 0
	vaxis.begin_session('👻 Ghostty 👻')
	defer {
		vaxis.end_session()
	}
	for {
		for {
			event := tty.poll() or { break }
			match event {
				vaxis.Key {
					if event.matches(u32(`c`), vaxis.Modifiers.init(false, false, true, false,
						false, false, false, false))
						|| event.matches(vaxis.escape, vaxis.Modifiers{}) {
						return 0
					}
				}
				vaxis.Mouse {}
			}
		}

		size := vaxis.terminal_size()
		print(draw_boo_frame(frames[frame], int(size.cols), int(size.rows))!)
		flush_stdout()
		frame++
		if frame == frames.len {
			frame = 0
		}
		time.sleep(boo_frame_rate * time.millisecond)
	}
	return 0
}
